import 'dart:async';
import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_inappwebview/flutter_inappwebview.dart';
import 'package:url_launcher/url_launcher.dart';

typedef JsonMap = Map<String, dynamic>;

const String kDeptLogoUrl =
    'https://lh3.googleusercontent.com/d/1JIydTyv1jIsJzTiGwIaACozrlWr8PJen';

// Embedded Staff & Super Admin Hub + Top-Right Student Window
const String kAdminPortalBase64 = '';
const String kStudentWindowBase64 = '';

void main() {
  WidgetsFlutterBinding.ensureInitialized();
  SystemChrome.setSystemUIOverlayStyle(
    const SystemUIOverlayStyle(
      statusBarColor: Color(0xFF0F172A),
      statusBarIconBrightness: Brightness.light,
      systemNavigationBarColor: Color(0xFF0F172A),
      systemNavigationBarIconBrightness: Brightness.light,
    ),
  );
  runApp(const MicroAdminApp());
}

class MicroAdminApp extends StatelessWidget {
  const MicroAdminApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Micro Admin',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        useMaterial3: true,
        scaffoldBackgroundColor: const Color(0xFF0F172A),
        colorScheme: ColorScheme.fromSeed(
          seedColor: const Color(0xFFF5B82E),
          brightness: Brightness.dark,
        ),
      ),
      home: const IntroSplashScreen(),
    );
  }
}

// ============================================================================
// CINEMATIC INTRO SCREEN (Square Rounded Icon + Transparent Back + Gold Split)
// ============================================================================
class IntroSplashScreen extends StatefulWidget {
  const IntroSplashScreen({super.key});

  @override
  State<IntroSplashScreen> createState() => _IntroSplashScreenState();
}

class _IntroSplashScreenState extends State<IntroSplashScreen>
    with SingleTickerProviderStateMixin {
  late final AnimationController _ctrl;
  late final Animation<double> _logoScale;
  late final Animation<double> _logoOpacity;
  late final Animation<double> _lineWidthFactor;
  late final Animation<double> _lineSplitGap;
  late final Animation<double> _sloganOpacity;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 2700),
    );

    _logoScale = Tween<double>(begin: 0.72, end: 1.0).animate(
      CurvedAnimation(
        parent: _ctrl,
        curve: const Interval(0.0, 0.42, curve: Cubic(0.22, 1.0, 0.36, 1.0)),
      ),
    );

    _logoOpacity = Tween<double>(begin: 0.0, end: 1.0).animate(
      CurvedAnimation(
        parent: _ctrl,
        curve: const Interval(0.0, 0.32, curve: Curves.easeOut),
      ),
    );

    _lineWidthFactor = Tween<double>(begin: 0.0, end: 1.0).animate(
      CurvedAnimation(
        parent: _ctrl,
        curve: const Interval(0.28, 0.62, curve: Cubic(0.22, 1.0, 0.36, 1.0)),
      ),
    );

    _lineSplitGap = Tween<double>(begin: 0.0, end: 44.0).animate(
      CurvedAnimation(
        parent: _ctrl,
        curve: const Interval(0.54, 0.86, curve: Cubic(0.22, 1.0, 0.36, 1.0)),
      ),
    );

    _sloganOpacity = Tween<double>(begin: 0.0, end: 1.0).animate(
      CurvedAnimation(
        parent: _ctrl,
        curve: const Interval(0.60, 0.92, curve: Curves.easeOut),
      ),
    );

    _ctrl.forward();

    Timer(const Duration(milliseconds: 3000), () {
      if (!mounted) return;
      Navigator.of(context).pushReplacement(
        PageRouteBuilder(
          transitionDuration: const Duration(milliseconds: 420),
          pageBuilder: (_, __, ___) => const AdminHubPortalScreen(),
          transitionsBuilder: (_, anim, __, child) =>
              FadeTransition(opacity: anim, child: child),
        ),
      );
    });
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  Widget _buildTransparentLogo() {
    return Container(
      width: 112,
      height: 112,
      decoration: BoxDecoration(
        color: Colors.transparent,
        borderRadius: BorderRadius.circular(24),
      ),
      clipBehavior: Clip.antiAlias,
      child: Image.asset(
        'assets/logo.png',
        fit: BoxFit.contain,
        errorBuilder: (_, __, ___) => Image.network(
          kDeptLogoUrl,
          fit: BoxFit.contain,
          errorBuilder: (_, __, ___) => const Icon(
            Icons.biotech_rounded,
            size: 68,
            color: Color(0xFFF5B82E),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFF0B111E),
      body: Container(
        width: double.infinity,
        height: double.infinity,
        decoration: const BoxDecoration(
          gradient: RadialGradient(
            center: Alignment(0.0, -0.2),
            radius: 1.15,
            colors: [
              Color(0xFF134E4A),
              Color(0xFF0F172A),
              Color(0xFF090D16),
            ],
          ),
        ),
        child: SafeArea(
          child: AnimatedBuilder(
            animation: _ctrl,
            builder: (context, _) {
              return Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Opacity(
                    opacity: _logoOpacity.value,
                    child: Transform.scale(
                      scale: _logoScale.value,
                      child: _buildTransparentLogo(),
                    ),
                  ),
                  const SizedBox(height: 22),
                  Opacity(
                    opacity: _logoOpacity.value,
                    child: const Text(
                      'MICRO ADMIN',
                      style: TextStyle(
                        color: Colors.white,
                        fontSize: 22,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 2.2,
                      ),
                    ),
                  ),
                  const SizedBox(height: 4),
                  Opacity(
                    opacity: _logoOpacity.value,
                    child: Text(
                      'STAFF & SUPER ADMIN HUB • BSU & BSNU',
                      style: TextStyle(
                        color: Colors.white.withOpacity(0.72),
                        fontSize: 10.5,
                        fontWeight: FontWeight.w700,
                        letterSpacing: 1.1,
                      ),
                    ),
                  ),
                  const SizedBox(height: 26),
                  SizedBox(
                    width: 300,
                    height: 60,
                    child: Stack(
                      alignment: Alignment.center,
                      children: [
                        Transform.translate(
                          offset: Offset(0, -_lineSplitGap.value / 2),
                          child: FractionallySizedBox(
                            widthFactor: _lineWidthFactor.value,
                            child: Container(
                              height: 2.2,
                              decoration: BoxDecoration(
                                color: const Color(0xFFF5B82E),
                                borderRadius: BorderRadius.circular(2),
                                boxShadow: [
                                  BoxShadow(
                                    color: const Color(0xFFF5B82E).withOpacity(0.45),
                                    blurRadius: 8,
                                  ),
                                ],
                              ),
                            ),
                          ),
                        ),
                        Opacity(
                          opacity: _sloganOpacity.value,
                          child: const Padding(
                            padding: EdgeInsets.symmetric(horizontal: 10),
                            child: Text(
                              'Understanding Microbes, Strengthening Health',
                              textAlign: TextAlign.center,
                              style: TextStyle(
                                color: Color(0xFFF5B82E),
                                fontSize: 12.5,
                                fontWeight: FontWeight.w800,
                                letterSpacing: 0.4,
                              ),
                            ),
                          ),
                        ),
                        Transform.translate(
                          offset: Offset(0, _lineSplitGap.value / 2),
                          child: FractionallySizedBox(
                            widthFactor: _lineWidthFactor.value,
                            child: Container(
                              height: 2.2,
                              decoration: BoxDecoration(
                                color: const Color(0xFFF5B82E),
                                borderRadius: BorderRadius.circular(2),
                                boxShadow: [
                                  BoxShadow(
                                    color: const Color(0xFFF5B82E).withOpacity(0.45),
                                    blurRadius: 8,
                                  ),
                                ],
                              ),
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              );
            },
          ),
        ),
      ),
    );
  }
}

// ============================================================================
// ADMIN & SUPER ADMIN PORTAL SCREEN (+ TOP-RIGHT STUDENT WINDOW TAB)
// ============================================================================
class AdminHubPortalScreen extends StatefulWidget {
  const AdminHubPortalScreen({super.key});

  @override
  State<AdminHubPortalScreen> createState() => _AdminHubPortalScreenState();
}

class _AdminHubPortalScreenState extends State<AdminHubPortalScreen> {
  InAppWebViewController? _webCtrl;
  PullToRefreshController? _pullToRefreshCtrl;
  String _activeMode = 'staff'; // 'staff' (default Admin Hub) or 'student' (Student Window)
  bool _isLoading = true;
  DateTime? _lastBackPressTime;

  late final String _decodedAdminHtml;
  late final String _decodedStudentWindowHtml;

  @override
  void initState() {
    super.initState();
    _decodedAdminHtml = utf8.decode(base64Decode(kAdminPortalBase64));
    _decodedStudentWindowHtml = utf8.decode(base64Decode(kStudentWindowBase64));

    _pullToRefreshCtrl = PullToRefreshController(
      settings: PullToRefreshSettings(
        color: const Color(0xFFF5B82E),
        backgroundColor: const Color(0xFF0F172A),
      ),
      onRefresh: () async {
        await _reloadCurrentPortal();
      },
    );
  }

  Future<void> _reloadCurrentPortal() async {
    if (_webCtrl == null) return;
    setState(() => _isLoading = true);
    final htmlData =
        _activeMode == 'staff' ? _decodedAdminHtml : _decodedStudentWindowHtml;
    await _webCtrl!.loadData(
      data: htmlData,
      mimeType: 'text/html',
      encoding: 'utf-8',
      baseUrl: WebUri('https://script.google.com/'),
    );
  }

  Future<void> _switchMode(String targetMode) async {
    if (_activeMode == targetMode) return;
    setState(() {
      _activeMode = targetMode;
      _isLoading = true;
    });
    await _reloadCurrentPortal();
  }

  Future<void> _handleAndroidBack() async {
    if (_webCtrl != null) {
      try {
        final res = await _webCtrl!.evaluateJavascript(
          source:
              "typeof window.handleAndroidBackButton === 'function' ? window.handleAndroidBackButton() : 'AT_ROOT'",
        );
        final status = (res ?? 'AT_ROOT').toString();
        if (status == 'HANDLED') {
          return; // Stepped back one view inside current portal
        }
      } catch (_) {}
    }

    // If inside the Student Window tab, pressing Back returns to Admin Hub Home first
    if (_activeMode == 'student') {
      await _switchMode('staff');
      return;
    }

    // At Admin Hub root Home screen: require double-press within 2 seconds to exit
    final now = DateTime.now();
    if (_lastBackPressTime == null ||
        now.difference(_lastBackPressTime!) > const Duration(seconds: 2)) {
      _lastBackPressTime = now;
      if (!mounted) return;
      ScaffoldMessenger.of(context).clearSnackBars();
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: const Text(
            'Press back again to exit',
            textAlign: TextAlign.center,
            style: TextStyle(
              color: Colors.white,
              fontWeight: FontWeight.w800,
              fontSize: 13,
            ),
          ),
          backgroundColor: const Color(0xFF0F172A),
          behavior: SnackBarBehavior.floating,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(999),
            side: const BorderSide(color: Color(0xFFF5B82E), width: 1.5),
          ),
          margin: const EdgeInsets.symmetric(horizontal: 64, vertical: 20),
          duration: const Duration(seconds: 2),
        ),
      );
      return;
    }

    await SystemNavigator.pop();
  }

  @override
  Widget build(BuildContext context) {
    final initialHtml =
        _activeMode == 'staff' ? _decodedAdminHtml : _decodedStudentWindowHtml;

    return PopScope(
      canPop: false,
      onPopInvokedWithResult: (didPop, _) async {
        if (didPop) return;
        await _handleAndroidBack();
      },
      child: Scaffold(
        backgroundColor: const Color(0xFF0F172A),
        body: SafeArea(
          child: Stack(
            children: [
              InAppWebView(
                initialData: InAppWebViewInitialData(
                  data: initialHtml,
                  mimeType: 'text/html',
                  encoding: 'utf-8',
                  baseUrl: WebUri('https://script.google.com/'),
                ),
                initialSettings: InAppWebViewSettings(
                  javaScriptEnabled: true,
                  domStorageEnabled: true,
                  databaseEnabled: true,
                  allowFileAccessFromFileURLs: true,
                  allowUniversalAccessFromFileURLs: true,
                  mediaPlaybackRequiresUserGesture: false,
                  supportZoom: false,
                  useShouldOverrideUrlLoading: true,
                ),
                pullToRefreshController: _pullToRefreshCtrl,
                onWebViewCreated: (controller) {
                  _webCtrl = controller;
                  controller.addJavaScriptHandler(
                    handlerName: 'switchAppMode',
                    callback: (args) {
                      final target = args.isNotEmpty
                          ? args[0].toString()
                          : (_activeMode == 'staff' ? 'student' : 'staff');
                      _switchMode(target);
                    },
                  );
                },
                onLoadStart: (_, __) {
                  if (mounted) setState(() => _isLoading = true);
                },
                onLoadStop: (_, __) async {
                  _pullToRefreshCtrl?.endRefreshing();
                  if (mounted) setState(() => _isLoading = false);
                },
                onReceivedError: (_, __, ___) {
                  _pullToRefreshCtrl?.endRefreshing();
                  if (mounted) setState(() => _isLoading = false);
                },
                shouldOverrideUrlLoading: (controller, navAction) async {
                  final uri = navAction.request.url;
                  if (uri == null) return NavigationActionPolicy.ALLOW;
                  final urlStr = uri.toString();
                  if (urlStr.startsWith('https://docs.google.com/') ||
                      urlStr.startsWith('https://drive.google.com/') ||
                      urlStr.startsWith('mailto:')) {
                    await launchUrl(uri, mode: LaunchMode.externalApplication);
                    return NavigationActionPolicy.CANCEL;
                  }
                  return NavigationActionPolicy.ALLOW;
                },
              ),

              if (_isLoading)
                Positioned(
                  top: 14,
                  left: 0,
                  right: 0,
                  child: Center(
                    child: Container(
                      width: 38,
                      height: 38,
                      padding: const EdgeInsets.all(8),
                      decoration: BoxDecoration(
                        color: const Color(0xFF0F172A),
                        shape: BoxShape.circle,
                        border: Border.all(
                          color: const Color(0xFFF5B82E),
                          width: 1.5,
                        ),
                        boxShadow: [
                          BoxShadow(
                            color: Colors.black.withOpacity(0.35),
                            blurRadius: 10,
                          ),
                        ],
                      ),
                      child: const CircularProgressIndicator(
                        strokeWidth: 2.5,
                        valueColor: AlwaysStoppedAnimation<Color>(
                          Color(0xFFF5B82E),
                        ),
                      ),
                    ),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }
}
